-- Session D (DECISIONS §38.2 item 6): the Levantine taxonomy merged into the dish library (§32.3).
-- 1. Every ingredient carries its food group, animal and cut, and whether it is an animal product, pork or alcohol,
--    so siyami and halal can be estimated from a recipe (shown as "estimated" until the merchant declares, §32.3; the
--    sesame/tahini and toum-egg menu rules are session 5c).
-- 2. Nine ingredients for Lebanese cuts and the EU-14 allergens the library lacked (lamb leg, shoulder and liver,
--    roast chicken, calamari, lupini beans, peanuts, celery, mustard) and four dishes that use them.
-- 3. `allergen_labels`: the 14 EU allergens in Arabic, English and French, for menus and filters.
-- The library block is generated by scripts/nutrition/library.ts (scripts/nutrition/library.test.ts keeps them equal).

alter table public.nutrition_ingredients
  add column food_group text check (food_group in ('red_meat', 'poultry', 'offal', 'processed_meat', 'fish', 'seafood', 'egg',
    'dairy', 'grain', 'legume', 'vegetable', 'fruit', 'nut_seed', 'herb_spice', 'fat_oil', 'sauce', 'pickle', 'sweetener', 'beverage')),
  add column animal text check (animal in ('lamb', 'beef', 'goat', 'chicken', 'fish', 'crustacean', 'mollusc')),
  add column cut text check (cut ~ '^[a-z_]+$'),
  add column animal_product boolean not null default false,
  add column pork boolean not null default false,
  add column alcohol boolean not null default false,
  add constraint nutrition_ingredients_cut_has_animal check (cut is null or animal is not null);
comment on column public.nutrition_ingredients.cut is 'Cut or form of the animal (leg, shoulder, liver, minced, breast...); null for non-animal ingredients.';

create table public.allergen_labels (
  allergen public.allergen primary key,
  eu14 boolean not null default true,
  name_ar text not null,
  name_en text not null,
  name_fr text not null,
  sort_order smallint not null
);
alter table public.allergen_labels enable row level security;
revoke all on table public.allergen_labels from public, anon, authenticated;
grant all on table public.allergen_labels to service_role;
grant select on table public.allergen_labels to anon, authenticated;
create policy allergen_labels_read on public.allergen_labels for select to anon, authenticated using (true);

-- BEGIN LIBRARY (generated by scripts/nutrition/library.ts; do not edit by hand)
on conflict (id) do update set name_en = excluded.name_en, fdc_query = excluded.fdc_query, source = excluded.source, allergens = excluded.allergens, kcal = excluded.kcal, protein_g = excluded.protein_g, carbs_g = excluded.carbs_g, fat_g = excluded.fat_g, sugar_g = excluded.sugar_g, fibre_g = excluded.fibre_g, sat_fat_g = excluded.sat_fat_g, sodium_mg = excluded.sodium_mg, food_group = excluded.food_group, animal = excluded.animal, cut = excluded.cut, animal_product = excluded.animal_product, pork = excluded.pork, alcohol = excluded.alcohol;
on conflict (id) do update set name_ar = excluded.name_ar, name_en = excluded.name_en, name_fr = excluded.name_fr, aliases = excluded.aliases, category = excluded.category, unit = excluded.unit, portion_g = excluded.portion_g, recipe = excluded.recipe, salt_g = excluded.salt_g;
-- END LIBRARY
